return ['domain'=>'zinn-cache-pro','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'ha','project-id-version'=>'zinn-cache-pro','pot-creation-date'=>'2026-09-03T18:22:39+00:00','po-revision-date'=>'2026-09-03T18:22:39+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Cache Engine'=>'Zinn® Cache Engine','https://zinndigital.com/wordpress-plugins/zinn-cache-pro'=>'https://zinndigital.com/wordpress-plugins/zinn-cache-pro','A complete caching and optimisation engine for WordPress: full-page cache, object cache, database cleanup and CSS/JS optimisation. Install this when your host does not provide a cache layer of its own — on Zinn Digital® hosting install Zinn® Cache instead. Full-page caching requires a LiteSpeed or OpenLiteSpeed server with the LSCache module. A GPLv3 fork of the LiteSpeed Cache plugin.'=>'Cikakken injin ajiyar wuri da haɓakawa don WordPress: cache na shafi guda, cache na abu, tsaftace database da haɓakar CSS/JS. Shigar da wannan lokacin da mai masaukin ku bai ba da Layer cache nasa ba — akan abokin masaukin Zinn Digital® shigar da Zinn® Cache maimakon haka. Ajiyar shafi guda yana buƙatar uwar garken LiteSpeed ko OpenLiteSpeed tare da tsarin LSCache. Reshen GPLv3 na plugin din LiteSpeed Cache.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','%d hours'=>'awa %d','%d hour'=>'awa %d','%d minutes'=>'%d mintoci','%d minute'=>'minti %d','Purged All!'=>'An Share Duka!','Purged the blog!'=>'An share shafin yanar gizon!','Purged the URL!'=>'An share URL din!','Purged!'=>'An share!','Failed to upgrade.'=>'An gaza sabuntawa.','Upgraded successfully.'=>'An inganta cikin nasara.','Dashboard'=>'Allon Kulawa','OptimaX'=>'OptimaX','Presets'=>'Abubuwan da aka tsara gaba','General'=>'Gabaɗaya','Cache'=>'Ma\'ajiyar wucin gadi','CDN'=>'CDN','Image Optimization'=>'Inganta Hotuna','Page Optimization'=>'Inganta Shafuka','Database'=>'Ma\'ajiyar bayanai','Crawler'